export function createEngine(store: Store, platform: Platform) {
  const { hashPassword, verifyPassword, newToken, hashToken } = platform
  const db: Data = store.data
  /** Road minutes already looked up, by rounded start, site and time. */
  const roadTimes = new Map<string, { minutes?: number; until: number }>()

  /**
   * Road minutes for the nearest few starts to a site, when the firm has drive
   * times. Answers are kept a few minutes; a failed lookup leaves them unset.
   */
  async function timeByRoad<T extends { start: { lat: number; lng: number }; miles: number; minutes?: number; by?: DriveTime['by'] }>(rows: T[], site: { id: string; lat: number; lng: number }) {
    if (!platform.driveMinutes || !rows.length) return rows
    const near = rows.slice(0, ROAD_TIMED)
    const key = (d: T) => `${d.start.lat.toFixed(3)},${d.start.lng.toFixed(3)}>${site.id}`
    const now = Date.now()
    const ask = near.filter((d) => !((roadTimes.get(key(d))?.until ?? 0) > now))
    if (ask.length) {
      try {
        const got = await platform.driveMinutes(
          ask.map((d) => d.start),
          { lat: site.lat, lng: site.lng },
        )
        ask.forEach((d, i) => roadTimes.set(key(d), { minutes: got[i], until: now + ROAD_KEEP_MS }))
      } catch {
        // No road times this time round: crow-flies distances still rank the vans.
      }
    }
    for (const d of near) {
      const minutes = roadTimes.get(key(d))?.minutes
      if (minutes !== undefined) Object.assign(d, { minutes: Math.round(minutes), by: 'road' })
    }
    near.sort((a, b) => (a.minutes ?? Infinity) - (b.minutes ?? Infinity) || a.miles - b.miles)
    rows.splice(0, near.length, ...near)
    return rows
  }

  /** Next human number for a firm: J-1001, INV-1001. New firms start at 1001. */
  function nextNumber(orgId: string, kind: string) {
    const key = `${orgId}:${kind}`
    db.counters[key] = (db.counters[key] ?? 1000) + 1
    return db.counters[key]
  }

  const publicUser = ({ passwordHash: _p, ...u }: User) => ({ ...u })

  function addUser(input: { email: string; name: string; password?: string; id?: string }) {
    const email = input.email.trim().toLowerCase()
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw invalid('a valid email is needed')
    if (!input.name?.trim()) throw invalid('a name is needed')
    if (db.users.some((u) => u.email === email)) throw invalid('that email is already in use')
    if (input.password !== undefined) {
      const weak = checkPassword(input.password)
      if (weak) throw invalid(weak)
    }
    const user: User = {
      id: input.id ?? newId('usr'),
      email,
      name: input.name.trim(),
      passwordHash: input.password === undefined ? undefined : hashPassword(input.password),
    }
    db.users.push(user)
    store.commit()
    return publicUser(user)
  }

  // ---------- sign-in ----------

  const SESSION_DAYS = 30
  const failures = new Map<string, number[]>()

  /** Email and password in, session token out. Ten wrong passwords in 15 minutes locks the email for a while. */
  function login(emailIn: string, password: string) {
    const email = String(emailIn ?? '').trim().toLowerCase()
    const now = Date.now()
    const recent = (failures.get(email) ?? []).filter((t) => now - t < 15 * 60 * 1000)
    if (recent.length >= 10) throw new EngineError('unauthenticated', 'too many attempts, try again in 15 minutes')
    const user = db.users.find((u) => u.email === email)
    if (!verifyPassword(String(password ?? ''), user?.passwordHash) || !user) {
      failures.set(email, [...recent, now])
      throw new EngineError('unauthenticated', 'email or password is wrong')
    }
    failures.delete(email)
    const token = newToken()
    db.sessions = db.sessions.filter((x) => x.expiresAt > new Date(now).toISOString())
    db.sessions.push({
      tokenHash: hashToken(token),
      userId: user.id,
      createdAt: new Date(now).toISOString(),
      expiresAt: new Date(now + SESSION_DAYS * DAY).toISOString(),
    })
    store.commit()
    return { token, user: publicUser(user), organisations: organisationsFor(user.id) }
  }

  function logout(token: string) {
    const h = hashToken(token)
    db.sessions = db.sessions.filter((x) => x.tokenHash !== h)
    store.commit()
  }

  /** Who a session token belongs to, if it is still valid. */
  function userForToken(token: string | undefined) {
    if (!token) return undefined
    const h = hashToken(token)
    const session = db.sessions.find((x) => x.tokenHash === h && x.expiresAt > new Date().toISOString())
    const user = session && db.users.find((u) => u.id === session.userId)
    return user ? publicUser(user) : undefined
  }

  /** A new person setting up their firm on Ardent. */
  function signUp(input: { email: string; password: string; name: string; firm: string; slug: string }) {
    if (input.password === undefined) throw invalid('a password is needed')
    const user = addUser({ email: input.email, name: input.name, password: input.password })
    createOrganisation(user.id, { name: input.firm, slug: input.slug })
    return login(user.email, input.password)
  }

  // ---------- signed photo links ----------

  db.secret ??= platform.randomSecret()
  const sign = (text: string) => platform.sign(db.secret!, text)
  const payments = createPayments({ db, store, platform, newId, nextNumber, invoiceTotals, sign, invalid, forbidden, notFound })
  /** The photo a signed link points at, if the link is genuine and in date. */
  function photoForLink(photoId: string, exp: string, sig: string) {
    if (!(Number(exp) > Date.now())) return undefined
    if (!platform.same(sign(`${photoId}:${exp}`), String(sig))) return undefined
    const p = db.photos.find((x) => x.id === photoId)
    return p?.uri.startsWith('ardent:') ? { orgId: p.orgId, id: p.id } : undefined
  }

  // ---------- retries ----------

  const REQUEST_MEMORY = 5000
  /** The answer already given for this request, if the app is retrying one the engine applied. */
  function recall(key: string) {
    return db.requests.find((r) => r.key === key)
  }
  function remember(key: string, result: unknown) {
    db.requests.push({ key, at: new Date().toISOString(), result })
    if (db.requests.length > REQUEST_MEMORY) db.requests.splice(0, db.requests.length - REQUEST_MEMORY)
    store.commit()
  }

  /** Sign-up: a new firm, with the person creating it as its owner. */
  function createOrganisation(userId: string, input: { name: string; slug: string; industry?: string }): Organisation {
    if (!db.users.some((u) => u.id === userId)) throw new EngineError('unauthenticated', 'sign in first')
    if (!input.name.trim()) throw invalid('the firm needs a name')
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(input.slug)) throw invalid('slug must be lower case words joined by hyphens')
    if (db.orgs.some((o) => o.slug === input.slug)) throw invalid('that slug is taken')
    const org: Organisation = {
      id: newId('org'),
      name: input.name.trim(),
      slug: input.slug,
      industry: input.industry ?? 'trades',
      createdAt: new Date().toISOString(),
    }
    db.orgs.push(org)
    db.memberships.push({ orgId: org.id, userId, role: 'owner' })
    store.commit()
    return { ...org }
  }

  /** Firms a person belongs to, for choosing one after sign-in. */
  function organisationsFor(userId: string): (Organisation & { role: Role })[] {
    return db.memberships
      .filter((m) => m.userId === userId)
      .flatMap((m) => {
        const org = db.orgs.find((o) => o.id === m.orgId)
        return org ? [{ ...org, role: m.role }] : []
      })
  }

  /* ---------- The firm's rules for Ardent, and what it uses ---------- */

  /** Ardent's playbook as published from Ardent HQ, or the one in the code until then. */
  /** Ardent's published playbook, less any rules Ardent switched off for everyone. */
  const playbook = (): FollowUp[] => (db.playbook ? db.playbook.rules.filter((r) => !db.playbook!.off?.includes(r.id)) : FOLLOW_UPS)

  /** The follow-ups a firm's phones ask. */
  function followUpsFor(orgId: string): FollowUpSet {
    const row = db.followUps.find((f) => f.orgId === orgId)
    return { playbook: playbook(), own: row?.own ?? [], off: row?.off ?? [] }
  }

  /** A firm's rules, the standard ones filled in wherever it hasn't chosen. */
  function rulesFor(orgId: string): Automation {
    const d = defaultAutomation()
    const row = db.automation.find((a) => a.orgId === orgId)
    if (!row) return d
    return {
      ...d,
      ...row,
      areas: { ...d.areas, ...row.areas },
      levels: { ...row.levels },
      chase: { ...d.chase, ...row.chase },
      officeHours: { ...d.officeHours, ...row.officeHours },
      limits: { ...d.limits, ...row.limits },
    }
  }

  const ukMonth = (iso: string) => ukDay(iso).slice(0, 7)
  function monthRow(orgId: string, month: string) {
    let row = db.usage.find((u) => u.orgId === orgId && u.month === month)
    if (!row) db.usage.push((row = { orgId, month, ai: 0, afterHours: 0, voice: 0, texts: 0 }))
    return row
  }
  const usageOf = (orgId: string, month: string): Usage =>
    usageFor(rulesFor(orgId), db.usage.find((u) => u.orgId === orgId && u.month === month) ?? { month, ai: 0, afterHours: 0, voice: 0, texts: 0 })

  /** Outside the firm's office hours, UK time. */
  function isAfterHours(rules: Automation, at: string) {
    const parts = Object.fromEntries(
      new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/London', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
        .formatToParts(new Date(at))
        .map((p) => [p.type, p.value]),
    )
    const day = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].indexOf(parts.weekday) + 1
    const hhmm = `${parts.hour}:${parts.minute}`
    const { from, to, days } = rules.officeHours
    return !(days.includes(day) && hhmm >= from && hhmm < to)
  }

  /**
   * Before Ardent does something that costs: may it go ahead under the firm's
   * plan and caps? AI stops at the owner's cap; calls need included
   * after-hours minutes or Ardent Voice; texts always go, extra ones at cost.
   */
  function allowance(orgId: string, kind: 'ai' | 'call' | 'text', at = new Date().toISOString()): { allowed: boolean; why?: string } {
    const rules = rulesFor(orgId)
    const u = usageOf(orgId, ukMonth(at))
    if (kind === 'ai') return u.aiPaused ? { allowed: false, why: "this month's AI cap is reached" } : { allowed: true }
    if (kind === 'text') return { allowed: true }
    if (!rules.areas.calls) return { allowed: false, why: 'answering is switched off' }
    if (rules.voice) return { allowed: true }
    if (!isAfterHours(rules, at)) return { allowed: false, why: 'answering in office hours is Ardent Voice' }
    const used = u.lines.find((l) => l.key === 'after_hours')!.used
    return used < (u.lines.find((l) => l.key === 'after_hours')!.included ?? 0) ? { allowed: true } : { allowed: false, why: "this month's after-hours minutes are used" }
  }

  /**
   * Count what Ardent used: AI in pence, calls in minutes, texts by the
   * message. After-hours calls use the included minutes first, then Ardent
   * Voice minutes. The owner is told in the log when the AI cap is reached.
   */
  function meter(orgId: string, kind: 'ai' | 'call' | 'text', amount: number, at = new Date().toISOString()): Usage {
    if (!(amount >= 0) || !Number.isFinite(amount)) throw invalid('usage is a number, zero or more')
    const rules = rulesFor(orgId)
    const month = ukMonth(at)
    const row = monthRow(orgId, month)
    const pausedBefore = row.ai >= rules.limits.aiPence
    if (kind === 'ai') row.ai += Math.round(amount)
    else if (kind === 'text') row.texts += Math.round(amount)
    else {
      const after = isAfterHours(rules, at)
      const fromIncluded = !after ? 0 : rules.voice ? Math.min(Math.max(0, PLAN.afterHoursMinutes - row.afterHours), amount) : amount
      row.afterHours += fromIncluded
      row.voice += amount - fromIncluded
    }
    if (kind === 'ai' && !pausedBefore && row.ai >= rules.limits.aiPence) {
      db.actions.push({ id: newId('act'), at, by: { kind: 'ardent' }, action: 'usage.aiPaused', summary: `AI paused: this month's ${pounds(rules.limits.aiPence)} cap is reached. Everything else carries on without it.`, orgId })
    }
    store.commit()
    return usageOf(orgId, month)
  }

  /** The client for one person in one firm. Rules are checked on every call. */
  function as(session: Session) {
    const { orgId, userId } = session

    const membership = (): Membership => {
      const m = db.memberships.find((x) => x.orgId === orgId && x.userId === userId)
      if (!m) throw forbidden('not a member of this firm')
      return m
    }
    const isOffice = () => membership().role !== 'field'
    const isOwner = () => membership().role === 'owner'
    const requireOffice = (what: string) => {
      if (!isOffice()) throw forbidden(`only the office can ${what}`)
    }
    /** The firm's own follow-up row, made on first change. */
    const firmFollowUps = () => {
      let row = db.followUps.find((f) => f.orgId === orgId)
      if (!row) {
        row = { orgId, own: [], off: [] }
        db.followUps.push(row)
      }
      return row
    }
    const myOperator = () => {
      membership()
      return db.operators.find((o) => o.orgId === orgId && o.userId === userId)
    }
    const assigned = (job: Job) => {
      const me = myOperator()
      return !!me && job.operatorIds.includes(me.id)
    }
    const canSeeJob = (job: Owned<Job>) => job.orgId === orgId && (isOffice() || assigned(job))

    const findJob = (id: string) => {
      const job = db.jobs.find((j) => j.id === id)
      if (!job || !canSeeJob(job)) throw notFound('job')
      return job
    }
    /** A job the caller may add to: office always, field while it's open. */
    const editableJob = (id: string) => {
      const job = findJob(id)
      if (!isOffice() && CLOSED.includes(job.status)) throw forbidden(`job is ${job.status}`)
      return job
    }
    /** Field may only act as themselves, on their own jobs. */
    const actingAs = (operatorId: string, job?: Owned<Job>) => {
      const op = db.operators.find((o) => o.id === operatorId && o.orgId === orgId)
      if (!op) throw notFound('operator')
      if (isOffice()) return op
      if (op.id !== myOperator()?.id) throw forbidden("can't act for another engineer")
      if (job && !assigned(job)) throw notFound('job')
      return op
    }
    /** Where an engineer is: their van's last fresh reading, else the job they're on. */
    const whereIs = (op: OperatorRow, now = Date.now()) => {
      const fix = op.location && now - Date.parse(op.location.at) <= FIX_FRESH_MS ? op.location : undefined
      if (fix) return { start: { lat: fix.lat, lng: fix.lng }, from: 'van' as const, seenAt: fix.at }
      const job = db.jobs.find((j) => j.id === op.currentJobId && j.orgId === orgId)
      const site = db.sites.find((x) => x.id === job?.siteId && x.orgId === orgId)
      return site ? { start: { lat: site.lat, lng: site.lng }, from: 'job' as const } : undefined
    }
    const fieldSees = (pred: (j: Owned<Job>) => boolean) =>
      db.jobs.some((j) => j.orgId === orgId && pred(j) && assigned(j))

    const done = <T,>(value: T) => {
      store.commit()
      return Promise.resolve(value)
    }
    /** Run a rule check and hand back a promise, so errors reject like a network call would. */
    const run = <T,>(fn: () => T): Promise<T> => {
      try {
        return Promise.resolve(fn())
      } catch (e) {
        return Promise.reject(e)
      }
    }

    const client: ArdentClient = {
      jobs: {
        list: (f = {}) =>
          run(() =>
            db.jobs
              .filter(
                (j) =>
                  canSeeJob(j) &&
                  (!f.status || f.status.includes(j.status)) &&
                  (!f.operatorId || j.operatorIds.includes(f.operatorId)) &&
                  (!f.from || j.start >= f.from) &&
                  (!f.to || j.start < f.to),
              )
              .map((j) => out(j)),
          ),
        get: (id) =>
          run(() => {
            const job = db.jobs.find((j) => j.id === id)
            return job && canSeeJob(job) ? out(job) : undefined
          }),
        create: (input) =>
          run(() => {
            requireOffice('book jobs')
            const customer = db.customers.find((c) => c.id === input.customerId && c.orgId === orgId)
            const site = db.sites.find((s) => s.id === input.siteId && s.orgId === orgId)
            if (!customer) throw notFound('customer')
            if (!site || site.customerId !== customer.id) throw invalid("site doesn't belong to that customer")
            for (const id of input.operatorIds) if (!db.operators.some((o) => o.id === id && o.orgId === orgId)) throw notFound('operator')
            if (input.end < input.start) throw invalid('job ends before it starts')
            const job: Owned<Job> = {
              ...structuredClone(input),
              lines: input.lines.map((l) => ({ ...l, id: l.id ?? newId('li') })),
              id: newId('job'),
              ref: `J-${nextNumber(orgId, 'job')}`,
              orgId,
            }
            db.jobs.push(job)
            return job
          }).then((job) => done(out(job))),
        update: (id, patch) =>
          run(() => {
            requireOffice('change bookings')
            const job = findJob(id)
            const allowed = ['title', 'trade', 'priority', 'start', 'end', 'notes', 'operatorIds'] as const
            for (const key of Object.keys(patch)) if (!(allowed as readonly string[]).includes(key)) throw invalid(`can't change ${key}`)
            for (const opId of patch.operatorIds ?? []) if (!db.operators.some((o) => o.id === opId && o.orgId === orgId)) throw notFound('operator')
            const next = { ...job, ...structuredClone(patch) }
            if (next.end < next.start) throw invalid('job ends before it starts')
            Object.assign(job, next)
            return job
          }).then((job) => done(out(job))),
        setStatus: (id, status) =>
          run(() => {
            const job = findJob(id)
            if (!isOffice() && job.status !== status && (CLOSED.includes(job.status) || !FIELD_STATUSES.includes(status))) {
              throw forbidden(`field can't move a job from ${job.status} to ${status}`)
            }
            const was = job.status
            job.status = status
            if (status === 'complete' && was !== 'complete') draftInvoice(job)
            return job
          }).then((job) => done(out(job))),
        addLine: (jobId, line) =>
          run(() => {
            const job = editableJob(jobId)
            if (!(line.quantity > 0)) throw invalid('quantity must be more than zero')
            if (!Number.isInteger(line.unitPrice)) throw invalid('unit price is whole pence')
            if (line.itemId && !db.priceList.some((i) => i.id === line.itemId && i.orgId === orgId)) throw notFound('price list item')
            if (line.fromVan) {
              if (!line.itemId) throw invalid('van stock needs a price list item')
              actingAs(line.fromVan, job)
              moveStock(line.fromVan, line.itemId, -line.quantity)
            }
            job.lines.push({ ...structuredClone(line), id: newId('li') })
            return job
          }).then((job) => done(out(job))),
        removeLine: (jobId, lineId) =>
          run(() => {
            const job = editableJob(jobId)
            const line = job.lines.find((l) => l.id === lineId)
            if (line?.fromVan && line.itemId) moveStock(line.fromVan, line.itemId, line.quantity)
            job.lines = job.lines.filter((l) => l.id !== lineId)
            return job
          }).then((job) => done(out(job))),
        setCheck: (jobId, key, state, detail) =>
          run(() => {
            const job = editableJob(jobId)
            const label = job.checks.find((c) => c.key === key)?.label ?? CHECK_LABEL[key]
            if (!label) throw invalid(`unknown check ${key}`)
            job.checks = [...job.checks.filter((c) => c.key !== key), { key, label, state, detail }]
            return job
          }).then((job) => done(out(job))),
      },

      customers: {
        list: () =>
          run(() =>
            db.customers
              .filter((c) => c.orgId === orgId && (isOffice() || fieldSees((j) => j.customerId === c.id)))
              .map(withBalance),
          ),
        get: (id) =>
          run(() => {
            const c = db.customers.find((x) => x.id === id && x.orgId === orgId)
            return c && (isOffice() || fieldSees((j) => j.customerId === c.id)) ? withBalance(c) : undefined
          }),
        create: (input) =>
          run(() => {
            requireOffice('add customers')
            if (!input.name?.trim()) throw invalid('the customer needs a name')
            if (!CUSTOMER_KINDS.includes(input.kind)) throw invalid(`unknown customer kind ${input.kind}`)
            const c: Owned<Customer> = { ...structuredClone(input), name: input.name.trim(), id: newId('cus'), balance: 0, orgId }
            db.customers.push(c)
            return c
          }).then((c) => done(withBalance(c))),
        update: (id, patch) =>
          run(() => {
            requireOffice('change customers')
            const c = db.customers.find((x) => x.id === id && x.orgId === orgId)
            if (!c) throw notFound('customer')
            const { id: _i, balance: _b, orgId: _o, ...rest } = structuredClone(patch) as Partial<Owned<Customer>>
            if (rest.name !== undefined && !rest.name.trim()) throw invalid('the customer needs a name')
            if (rest.kind !== undefined && !CUSTOMER_KINDS.includes(rest.kind)) throw invalid(`unknown customer kind ${rest.kind}`)
            Object.assign(c, rest)
            return c
          }).then((c) => done(withBalance(c))),
      },

      sites: {
        list: (f = {}) =>
          run(() =>
            db.sites
              .filter((s) => s.orgId === orgId && (!f.customerId || s.customerId === f.customerId) && (isOffice() || fieldSees((j) => j.siteId === s.id)))
              .map((s) => out(s)),
          ),
        get: (id) =>
          run(() => {
            const s = db.sites.find((x) => x.id === id && x.orgId === orgId)
            return s && (isOffice() || fieldSees((j) => j.siteId === s.id)) ? out(s) : undefined
          }),
        create: (input) =>
          run(() => {
            requireOffice('add sites')
            if (!db.customers.some((c) => c.id === input.customerId && c.orgId === orgId)) throw notFound('customer')
            if (!input.line1?.trim() || !input.postcode?.trim()) throw invalid('a site needs an address and postcode')
            const site = { ...structuredClone(input), postcode: input.postcode.trim().toUpperCase(), id: newId('sit'), orgId }
            db.sites.push(site)
            return site
          }).then((s) => done(out(s))),
      },

      approvals: {
        list: (f = {}) =>
          run(() => {
            requireOffice('see what waits for a yes')
            if (syncApprovals()) store.commit()
            return db.approvals
              .filter((a) => a.orgId === orgId && (f.status ? f.status.includes(a.status) : a.status === 'waiting'))
              .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
              .map((a) => out(a) as Approval)
          }),
        approve: async (id, version) => {
          const a = await run(() => {
            requireOffice('approve what Ardent drafted')
            syncApprovals()
            const row = db.approvals.find((x) => x.id === id && x.orgId === orgId)
            if (!row) throw notFound('approval')
            if (row.status !== 'waiting') throw invalid(row.status === 'stale' ? `no longer needed: ${row.note ?? 'it changed'}` : `already ${row.status}`)
            if (row.version !== version) throw invalid('it has changed since you looked: check it again')
            return row
          })
          if (a.kind === 'send_invoice') await client.invoices.send(a.invoiceId!, 'email')
          else if (a.kind === 'send_quote') await client.quotes.send(a.quoteId!, 'email')
          else if (a.kind === 'chase_invoice') {
            const inv = db.invoices.find((i) => i.id === a.invoiceId && i.orgId === orgId)
            if (inv) (inv.reminders ??= []).push(new Date().toISOString())
          } else if (a.kind === 'refund') await payments.refundNow(orgId, a.refundId!)
          a.status = 'approved'
          a.decidedAt = new Date().toISOString()
          a.decidedBy = me().name
          return done(out(a) as Approval)
        },
        reject: (id, note) =>
          run(() => {
            requireOffice('turn down what Ardent drafted')
            const row = db.approvals.find((x) => x.id === id && x.orgId === orgId)
            if (!row) throw notFound('approval')
            if (row.status !== 'waiting') throw invalid(`already ${row.status}`)
            row.status = 'rejected'
            row.decidedAt = new Date().toISOString()
            row.decidedBy = me().name
            if (note?.trim()) row.note = note.trim()
            const refund = row.kind === 'refund' && db.refunds.find((r) => r.id === row.refundId && r.orgId === orgId)
            if (refund) refund.status = 'turned_down'
            return row
          }).then((a) => done(out(a) as Approval)),
      },

      automation: {
        get: () =>
          run(() => {
            requireOffice("see Ardent's rules")
            const settings = rulesFor(orgId)
            return { settings, jobs: automationJobs(settings) }
          }),
        set: (patch) =>
          run(() => {
            if (!isOwner()) throw forbidden("only the owner changes Ardent's rules")
            const next = rulesFor(orgId)
            const whole = (n: unknown, lo: number, hi: number, what: string) => {
              if (!Number.isInteger(n) || (n as number) < lo || (n as number) > hi) throw invalid(`${what} is a whole number from ${lo} to ${hi}`)
              return n as number
            }
            for (const [k, on] of Object.entries(patch.areas ?? {})) {
              if (!AREAS.includes(k as never) || typeof on !== 'boolean') throw invalid(`unknown area ${k}`)
              next.areas[k as keyof Automation['areas']] = on
            }
            for (const [k, level] of Object.entries(patch.levels ?? {})) {
              const def = AUTOMATION_JOBS.find((j) => j.key === k)
              if (!def) throw invalid(`unknown job ${k}`)
              if (!def.allowed.includes(level)) throw invalid(`${def.name} can only be set to ${def.allowed.map((l) => `L${l}`).join(' or ')}`)
              if (level === def.standard) delete next.levels[k]
              else next.levels[k] = level
            }
            if (patch.chase) {
              const c = { ...next.chase, ...patch.chase }
              c.first = whole(c.first, 0, 60, 'the first reminder')
              c.firmer = whole(c.firmer, 1, 90, 'the firmer reminder')
              c.statement = whole(c.statement, 2, 120, 'the statement')
              c.gap = whole(c.gap, 1, 30, 'the gap between reminders')
              if (!(c.first < c.firmer && c.firmer < c.statement)) throw invalid('reminders go first, then firmer, then the statement')
              next.chase = c
            }
            if (patch.tone !== undefined) {
              if (!['friendly', 'plain', 'formal'].includes(patch.tone)) throw invalid('tone is friendly, plain or formal')
              next.tone = patch.tone
            }
            if (patch.signOff !== undefined) {
              const t = patch.signOff?.trim()
              if (t && t.length > 80) throw invalid('the sign-off is 80 characters at most')
              if (t) next.signOff = t
              else delete next.signOff
            }
            if (patch.officeHours) {
              const h = { ...next.officeHours, ...patch.officeHours }
              const time = /^([01]\d|2[0-3]):[0-5]\d$/
              if (!time.test(h.from) || !time.test(h.to) || h.from >= h.to) throw invalid('office hours are HH:MM, opening before closing')
              if (!Array.isArray(h.days) || !h.days.every((d) => Number.isInteger(d) && d >= 1 && d <= 7)) throw invalid('office days are 1 (Monday) to 7')
              next.officeHours = { ...h, days: [...new Set(h.days)].sort() }
            }
            if (patch.limits) {
              const l = { ...next.limits, ...patch.limits }
              l.aiPence = whole(l.aiPence, 0, 100_000, 'the AI cap in pence')
              l.messagesPerCustomerWeek = whole(l.messagesPerCustomerWeek, 1, 7, 'messages to one customer a week')
              next.limits = l
            }
            if (patch.voice !== undefined) {
              if (typeof patch.voice !== 'boolean') throw invalid('Ardent Voice is on or off')
              next.voice = patch.voice
            }
            db.automation = db.automation.filter((a) => a.orgId !== orgId)
            db.automation.push({ ...next, orgId })
            syncApprovals()
            return { settings: next, jobs: automationJobs(next) }
          }).then(done),
      },

      followUps: {
        get: () => run(() => followUpsFor(orgId)),
        switch: (id, on) =>
          run(() => {
            requireOffice('change the follow-up questions')
            const set = followUpsFor(orgId)
            if (![...set.playbook, ...set.own].some((r) => r.id === id)) throw notFound('follow-up question')
            if (typeof on !== 'boolean') throw invalid('a question is on or off')
            const row = firmFollowUps()
            row.off = on ? row.off.filter((x) => x !== id) : [...new Set([...row.off, id])]
            return followUpsFor(orgId)
          }).then(done),
        save: (input) =>
          run(() => {
            requireOffice('change the follow-up questions')
            const why = ruleProblem(input)
            if (why) throw invalid(why)
            const row = firmFollowUps()
            const was = input.id ? row.own.find((r) => r.id === input.id) : undefined
            if (input.id && !was) throw notFound('follow-up question')
            if (!was && row.own.length >= 50) throw invalid('a firm can have 50 of its own questions')
            const taken = [...followUpsFor(orgId).playbook.map((r) => r.id), ...row.own.map((r) => r.id)]
            const rule: FirmFollowUp = {
              id: was?.id ?? ownId(input.name, taken),
              name: input.name.trim(),
              why: input.why.trim(),
              ...(input.hint?.trim() ? { hint: input.hint.trim() } : {}),
              ...(input.trades ? { trades: [...input.trades] } : {}),
              after: input.after === 'any' ? 'any' : [...input.after],
              when: input.when.map((c) => ({ ...c })),
              ask: input.ask.trim(),
              replies: input.replies.map((b) => ({ ...b })),
              ...(input.shared ? { shared: true } : {}),
              by: me().name,
              updatedAt: new Date().toISOString(),
            }
            row.own = was ? row.own.map((r) => (r === was ? rule : r)) : [...row.own, rule]
            return followUpsFor(orgId)
          }).then(done),
        remove: (id) =>
          run(() => {
            requireOffice('change the follow-up questions')
            const row = firmFollowUps()
            if (!row.own.some((r) => r.id === id)) throw notFound("the firm's own question")
            row.own = row.own.filter((r) => r.id !== id)
            row.off = row.off.filter((x) => x !== id)
            return followUpsFor(orgId)
          }).then(done),
      },

      usage: {
        get: (opts = {}) =>
          run(() => {
            requireOffice('see what Ardent has used')
            const month = opts.month ?? ukMonth(new Date().toISOString())
            if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) throw invalid('month is YYYY-MM')
            return usageOf(orgId, month)
          }),
      },

      log: {
        list: (f = {}) =>
          run(() => {
            requireOffice('see the log')
            const limit = Math.min(500, Math.max(1, f.limit ?? 100))
            const rows: ActionEntry[] = []
            for (let i = db.actions.length - 1; i >= 0 && rows.length < limit; i--) {
              const e = db.actions[i]
              if (e.orgId === orgId && (!f.jobId || e.jobId === f.jobId)) rows.push(out(e) as ActionEntry)
            }
            return rows
          }),
      },

      brief: {
        get: async (opts = {}) => {
          const day = opts.day ?? ukDay(new Date().toISOString())
          if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) throw invalid('day is YYYY-MM-DD')
          const attention = await client.attention.list()
          const waiting = (await client.approvals.list()).length
          return run(() =>
            composeBrief({
              day,
              now: new Date().toISOString(),
              jobs: db.jobs.filter((j) => j.orgId === orgId).map((j) => out(j) as Job),
              invoices: db.invoices.filter((i) => i.orgId === orgId).map((i) => out(i) as Invoice),
              attention,
              waiting,
            }),
          )
        },
      },

      attention: {
        list: () =>
          run(() => {
            requireOffice('see the attention list')
            const now = new Date()
            const iso = now.toISOString()
            const today = iso.slice(0, 10)
            const soon = new Date(now.getTime() + DUE_SOON_DAYS * DAY).toISOString().slice(0, 10)
            const items: Exception[] = []
            const siteName = (id: string) => db.sites.find((s) => s.id === id)?.line1 ?? 'site'
            for (const op of db.operators.filter((o) => o.orgId === orgId)) {
              for (const r of op.registrations) {
                if (r.expires < today) items.push({ id: `att_reg_${op.id}_${r.number}`, at: `${r.expires}T00:00:00Z`, who: op.name, rule: 'Registration expired', detail: `${r.body} ${r.number} lapsed ${r.expires}`, outcome: 'blocked' })
                else if (r.expires <= soon) items.push({ id: `att_reg_${op.id}_${r.number}`, at: iso, who: op.name, rule: 'Registration expiring', detail: `${r.body} ${r.number} lapses ${r.expires}`, outcome: 'chasing' })
              }
              if (op.state === 'delayed') items.push({ id: `att_late_${op.id}`, at: iso, who: op.name, rule: 'Running late', detail: `${db.jobs.find((j) => j.id === op.currentJobId)?.ref ?? 'Next job'}${op.etaMinutes ? `, ETA +${op.etaMinutes} min` : ''}`, outcome: 'chasing' })
            }
            for (const op of db.operators.filter((o) => o.orgId === orgId)) {
              const low = db.stock.filter((x) => x.orgId === orgId && x.operatorId === op.id && x.quantity <= x.min && db.priceList.some((i) => i.id === x.itemId && !i.archived))
              if (!low.length) continue
              const names = low.map((x) => `${db.priceList.find((i) => i.id === x.itemId)!.name} (${x.quantity} left)`)
              items.push({ id: `att_stock_${op.id}`, at: iso, who: op.name, rule: 'Van stock low', detail: `${op.van}: ${names.slice(0, 3).join(', ')}${names.length > 3 ? ` and ${names.length - 3} more` : ''}`, outcome: 'chasing' })
            }
            for (const r of db.gasRecords.filter((x) => x.orgId === orgId && x.status === 'issued')) {
              for (const a of r.appliances.filter((x) => x.safe === false)) {
                items.push({ id: `att_gas_${r.id}_${a.id}`, at: r.issuedAt!, who: db.customers.find((c) => c.id === r.customerId)?.name ?? 'Customer', rule: a.unsafe === 'immediately_dangerous' ? 'Immediately dangerous' : 'Appliance unsafe', detail: `${a.type}, ${a.location}, on ${r.ref}${a.defects ? `: ${a.defects}` : ''}`, outcome: 'blocked' })
              }
            }
            for (const c of db.certificates.filter((x) => x.orgId === orgId && certificateState(x, today) === 'overdue')) {
              items.push({ id: `att_cert_${c.id}`, at: `${c.expires}T00:00:00Z`, who: db.customers.find((x) => x.id === db.sites.find((s) => s.id === c.siteId)?.customerId)?.name ?? 'Customer', rule: `${c.kind} overdue`, detail: `${siteName(c.siteId)}, expired ${c.expires}`, outcome: 'blocked' })
            }
            for (const inv of db.invoices.filter((i) => i.orgId === orgId && OWING.includes(i.status) && i.dueAt && i.dueAt < iso)) {
              items.push({ id: `att_inv_${inv.id}`, at: inv.dueAt!, who: db.customers.find((x) => x.id === inv.customerId)?.name ?? 'Customer', rule: 'Invoice overdue', detail: `${inv.ref}, due ${inv.dueAt!.slice(0, 10)}`, outcome: 'chasing' })
            }
            for (const j of db.jobs.filter((x) => x.orgId === orgId && x.status === 'booked' && x.start < iso && x.end > iso)) {
              items.push({ id: `att_job_${j.id}`, at: j.start, who: j.ref, rule: 'Not started', detail: `${j.title}, booked for ${j.start.slice(11, 16)}`, outcome: 'chasing' })
            }
            for (const j of db.jobs.filter((x) => x.orgId === orgId && x.status === 'paused')) {
              const note = db.notes.filter((n) => n.jobId === j.id).sort((a, b) => b.at.localeCompare(a.at))[0]
              const who = db.operators.find((o) => o.id === (note?.operatorId ?? j.operatorIds[0]))?.name ?? j.ref
              items.push({ id: `att_pause_${j.id}`, at: note?.at ?? j.start, who, rule: `${j.ref} paused`, detail: note?.body ?? `${j.title}, waiting`, outcome: 'chasing' })
            }
            for (const r of db.jobRequests.filter((x) => x.orgId === orgId)) advance(r)
            for (const r of db.jobRequests.filter((x) => x.orgId === orgId && x.status === 'unfilled' && now.getTime() - Date.parse(x.createdAt) < UNFILLED_SHOWN_MS)) {
              const job = db.jobs.find((j) => j.id === r.jobId)
              if (!job || job.operatorIds.length) continue
              items.push({ id: `att_req_${r.id}`, at: r.createdAt, who: r.brief.ref, rule: 'No one took it', detail: `${r.brief.title}, ${r.brief.area}: ${r.offers.length ? `${r.offers.length} asked, no one free` : 'no one could be asked'}`, outcome: 'blocked' })
            }
            const payer = (customerId: string) => db.customers.find((c) => c.id === customerId)?.name ?? 'Customer'
            for (const d of db.disputes.filter((x) => x.orgId === orgId && x.status === 'needs_reply')) {
              const c = db.charges.find((x) => x.id === d.chargeId)
              items.push({ id: `att_dsp_${d.id}`, at: d.openedAt, who: payer(c?.customerId ?? ''), rule: 'Card dispute', detail: `${pounds(d.amount)} on ${c?.label ?? 'a payment'}: ${d.reason}. Evidence ready, reply by ${shortDate(d.replyBy)}`, outcome: 'blocked' })
            }
            for (const p of db.plans.filter((x) => x.orgId === orgId && x.status === 'payment_failed')) {
              items.push({ id: `att_dd_${p.id}`, at: p.lastFailedAt ?? p.createdAt, who: payer(p.customerId), rule: 'Direct Debit failed', detail: `${p.ref}, ${pounds(p.monthly)} a month: give them a ring`, outcome: 'chasing' })
            }
            return items.sort((a, b) => b.at.localeCompare(a.at))
          }),
      },

      certificates: {
        list: (f = {}) =>
          run(() =>
            db.certificates
              .filter((c) => c.orgId === orgId && (!f.siteId || c.siteId === f.siteId) && (isOffice() || fieldSees((j) => j.siteId === c.siteId)))
              .map((c) => ({ ...out(c), state: certificateState(c) })),
          ),
      },

      priceList: {
        list: (opts = {}) =>
          run(() => {
            const office = isOffice()
            return db.priceList
              .filter((i) => i.orgId === orgId && (!i.archived || (office && opts.archived)))
              .map((i) => {
                const item = out(i) as PriceItem
                if (!office) delete item.cost
                return item
              })
              .sort((a, b) => a.name.localeCompare(b.name))
          }),
        create: (input) =>
          run(() => {
            requireOffice('keep the price list')
            const item: Owned<PriceItem> = { ...checkItem(structuredClone(input)), id: newId('itm'), orgId }
            db.priceList.push(item)
            return item
          }).then((i) => done(out(i) as PriceItem)),
        update: (id, patch) =>
          run(() => {
            requireOffice('keep the price list')
            const item = db.priceList.find((i) => i.id === id && i.orgId === orgId)
            if (!item) throw notFound('price list item')
            const { id: _i, orgId: _o, ...rest } = structuredClone(patch) as Record<string, unknown>
            const cleared = (['code', 'cost', 'trade'] as const).filter((k) => k in rest && (rest[k] === null || rest[k] === undefined))
            for (const k of cleared) delete rest[k]
            const next = checkItem({ ...out(item), ...rest } as PriceItem)
            for (const k of cleared) delete next[k]
            Object.assign(item, next)
            for (const k of cleared) delete item[k]
            return item
          }).then((i) => done(out(i) as PriceItem)),
      },

      stock: {
        list: (f = {}) =>
          run(() => {
            const me = myOperator()?.id
            if (!isOffice() && f.operatorId && f.operatorId !== me) throw forbidden("can't see another engineer's van")
            const who = isOffice() ? f.operatorId : me
            return db.stock.filter((x) => x.orgId === orgId && (!who || x.operatorId === who) && (isOffice() || who)).map((x) => out(x) as StockLevel)
          }),
        set: (operatorId, itemId, quantity, min) =>
          run(() => {
            requireOffice('restock vans')
            if (!db.operators.some((o) => o.id === operatorId && o.orgId === orgId)) throw notFound('operator')
            const item = db.priceList.find((i) => i.id === itemId && i.orgId === orgId)
            if (!item) throw notFound('price list item')
            if (!item.stocked) throw invalid(`${item.name} isn't carried on the vans`)
            if (!Number.isInteger(quantity) || quantity < 0) throw invalid('stock is a whole number of zero or more')
            if (min !== undefined && (!Number.isInteger(min) || min < 0)) throw invalid('the low mark is a whole number of zero or more')
            const row = stockRow(operatorId, itemId)
            row.quantity = quantity
            if (min !== undefined) row.min = min
            return row
          }).then((x) => done(out(x) as StockLevel)),
      },

      gasRecords: {
        list: (f = {}) =>
          run(() =>
            db.gasRecords
              .filter((r) => r.orgId === orgId && (!f.siteId || r.siteId === f.siteId) && (isOffice() || fieldSees((j) => j.siteId === r.siteId)))
              .map((r) => out(r) as GasSafetyRecord)
              .sort((a, b) => (b.issuedAt ?? '9').localeCompare(a.issuedAt ?? '9')),
          ),
        forJob: (jobId) => run(() => (findJob(jobId), db.gasRecords.filter((r) => r.orgId === orgId && r.jobId === jobId).map((r) => out(r) as GasSafetyRecord))),
        create: (jobId, operatorId) =>
          run(() => {
            const job = editableJob(jobId)
            actingAs(operatorId, job)
            const open = db.gasRecords.find((r) => r.orgId === orgId && r.jobId === jobId && r.status === 'draft')
            if (open) return open
            // Start from what was there last time: same appliances, fresh readings.
            const last = db.gasRecords.filter((r) => r.orgId === orgId && r.siteId === job.siteId && r.status === 'issued').sort((a, b) => (b.issuedAt ?? '').localeCompare(a.issuedAt ?? ''))[0]
            const rec: Owned<GasSafetyRecord> = {
              id: newId('gsr'),
              ref: `CP-${nextNumber(orgId, 'cp12')}`,
              jobId,
              siteId: job.siteId,
              customerId: job.customerId,
              operatorId,
              appliances: (last?.appliances ?? []).map((a) => ({ id: newId('app'), location: a.location, type: a.type, make: a.make, model: a.model, flue: a.flue, landlords: a.landlords, checks: pendingChecks() })),
              installation: { tightness: 'pending', ecv: 'pending', bonding: 'pending', pipework: 'pending', coAlarm: 'pending' },
              status: 'draft',
              orgId,
            }
            db.gasRecords.push(rec)
            return rec
          }).then((r) => done(out(r) as GasSafetyRecord)),
        saveAppliance: (id, input) =>
          run(() => {
            const rec = draftRecord(id)
            if (!String(input.location ?? '').trim()) throw invalid('say where the appliance is')
            if (!String(input.type ?? '').trim()) throw invalid('say what the appliance is')
            if (!FLUES.includes(input.flue)) throw invalid(`unknown flue type ${input.flue}`)
            const checks = { ...pendingChecks(), ...(input.checks ?? {}) }
            for (const k of APPLIANCE_CHECKS) if (!VERDICTS.includes(checks[k])) throw invalid(`unknown answer ${checks[k]}`)
            if (input.unsafe && !['at_risk', 'immediately_dangerous'].includes(input.unsafe)) throw invalid(`unknown unsafe category ${input.unsafe}`)
            const a: GasAppliance = {
              id: input.id ?? newId('app'),
              location: input.location.trim(),
              type: input.type.trim(),
              make: input.make?.trim() || undefined,
              model: input.model?.trim() || undefined,
              flue: input.flue,
              landlords: input.landlords !== false,
              pressure: reading(input.pressure, 'operating pressure'),
              heatInput: reading(input.heatInput, 'heat input'),
              co: reading(input.co, 'CO'),
              co2: reading(input.co2, 'CO2'),
              ratio: reading(input.ratio, 'CO/CO2 ratio'),
              checks: { flue: checks.flue, ventilation: checks.ventilation, safetyDevice: checks.safetyDevice, spillage: checks.spillage },
              safe: typeof input.safe === 'boolean' ? input.safe : undefined,
              defects: input.defects?.trim() || undefined,
              unsafe: input.unsafe,
            }
            // A safe appliance can't also be classed unsafe.
            if (a.safe) delete a.unsafe
            const i = rec.appliances.findIndex((x) => x.id === a.id)
            if (input.id && i < 0) throw notFound('appliance')
            if (i >= 0) rec.appliances[i] = a
            else rec.appliances.push(a)
            return rec
          }).then((r) => done(out(r) as GasSafetyRecord)),
        removeAppliance: (id, applianceId) =>
          run(() => {
            const rec = draftRecord(id)
            rec.appliances = rec.appliances.filter((a) => a.id !== applianceId)
            return rec
          }).then((r) => done(out(r) as GasSafetyRecord)),
        setInstallation: (id, key, verdict) =>
          run(() => {
            const rec = draftRecord(id)
            if (!INSTALLATION.includes(key)) throw invalid(`unknown check ${key}`)
            if (!VERDICTS.includes(verdict)) throw invalid(`unknown answer ${verdict}`)
            rec.installation[key] = verdict
            return rec
          }).then((r) => done(out(r) as GasSafetyRecord)),
        issue: (id) =>
          run(() => {
            const rec = draftRecord(id)
            const missing = gasGaps(rec)
            if (missing.length) throw invalid(`not finished: ${missing.join('; ')}`)
            const now = new Date().toISOString()
            const issued = now.slice(0, 10)
            rec.status = 'issued'
            rec.issuedAt = now
            rec.expires = yearOn(issued)
            const cert = { id: newId('cer'), kind: 'CP12' as const, siteId: rec.siteId, jobId: rec.jobId, issued, expires: rec.expires, state: 'valid' as const, orgId }
            db.certificates.push(cert)
            rec.certificateId = cert.id
            // The job's tightness gate follows the record.
            const job = db.jobs.find((j) => j.id === rec.jobId)
            if (job) job.checks = [...job.checks.filter((c) => c.key !== 'gas_tightness'), { key: 'gas_tightness', label: job.checks.find((c) => c.key === 'gas_tightness')?.label ?? CHECK_LABEL.gas_tightness, state: rec.installation.tightness === 'pending' ? 'pending' : rec.installation.tightness, detail: `${rec.ref} issued` }]
            return rec
          }).then((r) => done(out(r) as GasSafetyRecord)),
      },

      operators: {
        list: () =>
          run(() => {
            membership()
            const office = isOffice()
            const me = myOperator()?.id
            return db.operators
              .filter((o) => o.orgId === orgId)
              .map((o) => {
                const row = out(o) as Operator
                // Where a van is stays between that engineer and the office.
                if (!office && o.id !== me) delete row.location
                return row
              })
          }),
        me: () =>
          run(() => {
            const me = myOperator()
            if (!me) throw notFound('crew record for this sign-in')
            return out(me)
          }),
        setState: (id, state, jobId) =>
          run(() => {
            const op = actingAs(id)
            if (jobId !== undefined) findJob(jobId)
            op.state = state
            if (jobId !== undefined) op.currentJobId = jobId
            // Off shift, the van's whereabouts are nobody's business, and nobody sends them work.
            if (state === 'off_shift') {
              delete op.location
              delete op.standby
            }
            return op
          }).then((op) => done(out(op) as Operator)),
        setLocation: (id, fix) =>
          run(() => {
            const op = db.operators.find((o) => o.id === id && o.orgId === orgId)
            if (!op || op.id !== myOperator()?.id) throw forbidden('only the engineer shares where their van is')
            const { lat, lng, accuracy, at } = fix ?? ({} as VanFix)
            if (!Number.isFinite(lat) || !Number.isFinite(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180) throw invalid('that is not a place on the map')
            if (accuracy !== undefined && !(Number.isFinite(accuracy) && accuracy >= 0)) throw invalid('accuracy is metres of zero or more')
            const when = Date.parse(at)
            if (!Number.isFinite(when) || when > Date.now() + 5 * 60 * 1000) throw invalid('the reading needs the time it was taken')
            // A reading sent late after lost signal, or one from off shift, changes nothing.
            if (op.state === 'off_shift' || (op.location && op.location.at >= at)) return op
            op.location = { lat, lng, ...(accuracy !== undefined ? { accuracy: Math.round(accuracy) } : {}), at: new Date(when).toISOString() }
            return op
          }).then((op) => done(out(op) as Operator)),
        setStandby: (id, standby) =>
          run(() => {
            const op = db.operators.find((o) => o.id === id && o.orgId === orgId)
            if (!op) throw notFound('operator')
            const self = op.id === myOperator()?.id
            // The office can stand someone down, but only the engineer says they're free.
            if (!self && (standby || !isOffice())) throw forbidden('only the engineer puts themselves on standby')
            if (!standby) {
              delete op.standby
              if (op.role === 'freelance' && op.state === 'on_call') {
                op.state = 'off_shift'
                delete op.location
              }
              return op
            }
            const until = Date.parse(standby.until)
            if (!Number.isFinite(until) || until <= Date.now()) throw invalid('standby needs a finish time later than now')
            if (until > Date.now() + DAY) throw invalid('standby is for a day at most')
            if (!(typeof standby.radius === 'number' && standby.radius >= 1 && standby.radius <= 100)) throw invalid('radius is 1 to 100 miles')
            // Working from the same place as last time unless they say otherwise.
            const b = standby.base ?? op.standby?.base
            if (b && (!Number.isFinite(b.lat) || !Number.isFinite(b.lng) || Math.abs(b.lat) > 90 || Math.abs(b.lng) > 180)) throw invalid('that is not a place on the map')
            op.standby = { until: new Date(until).toISOString(), radius: Math.round(standby.radius), ...(b ? { base: { lat: b.lat, lng: b.lng } } : {}) }
            if (op.state === 'off_shift') op.state = 'on_call'
            return op
          }).then((op) => done(out(op) as Operator)),
      },

      requests: {
        list: (f = {}) =>
          run(() => {
            membership()
            const office = isOffice()
            const me = myOperator()?.id
            const open = f.open !== false
            let changed = false
            const rows = db.jobRequests.filter((r) => r.orgId === orgId && (!f.jobId || r.jobId === f.jobId))
            for (const r of rows) changed = advance(r) || changed
            if (changed) store.commit()
            if (office) return rows.filter((r) => !open || r.status === 'open').map((r) => out(r) as JobRequest)
            return rows
              .filter((r) => r.offers.some((o) => o.operatorId === me && (open ? o.status === 'offered' : o.status !== 'waiting')))
              .map((r) => fieldView(r, me!))
          }),
        create: async (jobId, opts = {}) => {
          const plan = await run(() => {
            requireOffice('send job requests')
            const job = findJob(jobId)
            if (CLOSED.includes(job.status) || job.status === 'complete') throw invalid(`job is ${job.status}`)
            if (db.jobRequests.some((r) => r.orgId === orgId && r.jobId === jobId && (advance(r), r.status === 'open'))) throw invalid('already asking the crew about this job')
            const mode = opts.mode ?? 'one'
            if (mode !== 'one' && mode !== 'all') throw invalid(`unknown mode ${mode}`)
            const wait = opts.wait ?? OFFER_WAIT
            if (!Number.isInteger(wait) || wait < 15 || wait > 600) throw invalid('wait is 15 to 600 seconds')
            const site = db.sites.find((x) => x.id === job.siteId && x.orgId === orgId)!
            return { job, site, mode, wait, ...whoCanGo(job, site) }
          })
          const { job, site, mode, wait, going: all, skipped } = plan
          // Only those whose whereabouts are known are timed by road; the rest go after them.
          const going = [...(await timeByRoad(all.filter((g) => g.known), site)), ...all.filter((g) => !g.known)]
          return run(() => {
            const now = Date.now()
            // Staff before subbies before freelancers; nearest first within each.
            const rank = (op: OperatorRow) => (op.role === 'freelance' ? 2 : op.role === 'subcontractor' ? 1 : 0)
            const ordered = going
              .map((g, i) => ({ ...g, i }))
              .sort((a, b) => rank(a.op) - rank(b.op) || a.i - b.i)
            const req: Owned<JobRequest> = {
              id: newId('req'),
              jobId: job.id,
              mode,
              wait,
              status: ordered.length ? 'open' : 'unfilled',
              brief: { ref: job.ref, title: job.title, trade: job.trade, priority: job.priority, start: job.start, end: job.end, area: `${site.town}, ${site.postcode.split(' ')[0]}`, lat: site.lat, lng: site.lng },
              offers: ordered.map((g) => ({ operatorId: g.op.id, status: 'waiting' as const, ...(g.known ? { miles: g.miles } : {}), ...(g.minutes !== undefined ? { minutes: g.minutes } : {}) })),
              skipped,
              createdAt: new Date(now).toISOString(),
              orgId,
            }
            for (const o of mode === 'all' ? req.offers : req.offers.slice(0, 1)) sendOffer(req, o, now)
            db.jobRequests.push(req)
            return req
          }).then((r) => done(out(r) as JobRequest))
        },
        respond: (id, answer, reason) =>
          run(() => {
            const me = myOperator()
            if (!me) throw forbidden('only the engineer it was offered to can answer')
            const req = db.jobRequests.find((r) => r.id === id && r.orgId === orgId)
            const offer = req?.offers.find((o) => o.operatorId === me.id && o.status !== 'waiting')
            if (!req || !offer) throw notFound('job request')
            advance(req)
            if (offer.status !== 'offered') {
              store.commit()
              throw invalid(req.status === 'filled' ? 'someone else has taken it' : offer.status === 'expired' ? 'too late, it has gone to someone else' : req.status === 'withdrawn' ? 'the office called it off' : `already ${offer.status}`)
            }
            const now = new Date().toISOString()
            offer.answeredAt = now
            if (answer === 'accept') {
              offer.status = 'accepted'
              req.status = 'filled'
              req.filledBy = me.id
              for (const o of req.offers) if (o !== offer && (o.status === 'offered' || o.status === 'waiting')) o.status = 'closed'
              const job = db.jobs.find((j) => j.id === req.jobId && j.orgId === orgId)
              if (job) {
                job.operatorIds = [me.id]
                if (job.status === 'enquiry' || job.status === 'quoted') job.status = 'booked'
              }
            } else if (answer === 'decline') {
              if (reason !== undefined && !DECLINE_REASONS.includes(reason)) throw invalid(`unknown reason ${reason}`)
              offer.status = 'declined'
              if (reason) offer.reason = reason
              advance(req)
            } else throw invalid(`answer is accept or decline`)
            return fieldView(req, me.id)
          }).then((r) => done(r)),
        withdraw: (id) =>
          run(() => {
            requireOffice('call off job requests')
            const req = db.jobRequests.find((r) => r.id === id && r.orgId === orgId)
            if (!req) throw notFound('job request')
            findJob(req.jobId)
            advance(req)
            if (req.status === 'open') {
              req.status = 'withdrawn'
              for (const o of req.offers) if (o.status === 'offered' || o.status === 'waiting') o.status = 'closed'
            }
            return req
          }).then((r) => done(out(r) as JobRequest)),
      },

      travel: {
        get: () => run(() => (requireOffice('see drive times'), { roadTimes: !!platform.driveMinutes })),
        list: async ({ siteId }) => {
          const rows = await run(() => {
            requireOffice('see where the vans are')
            const site = db.sites.find((x) => x.id === siteId && x.orgId === orgId)
            if (!site) throw notFound('site')
            const now = Date.now()
            const found: (DriveTime & { start: { lat: number; lng: number } })[] = []
            for (const op of db.operators.filter((o) => o.orgId === orgId && o.state !== 'off_shift')) {
              const at = whereIs(op, now)
              if (!at) continue
              found.push({ operatorId: op.id, miles: Math.round(milesApart(at.start, site) * 10) / 10, by: 'straight_line', from: at.from, ...(at.seenAt ? { seenAt: at.seenAt } : {}), start: at.start })
            }
            return { site, found: found.sort((a, b) => a.miles - b.miles) }
          })
          const { site, found } = rows
          await timeByRoad(found, site)
          return found.map(({ start: _s, ...d }) => d)
        },
      },

      time: {
        start: (entry) =>
          run(() => {
            const job = entry.jobId ? findJob(entry.jobId) : undefined
            actingAs(entry.operatorId, job)
            const t = { ...entry, id: newId('tim'), orgId }
            db.time.push(t)
            return t
          }).then((t) => done(out(t))),
        stop: (id, at = new Date().toISOString()) =>
          run(() => {
            const t = db.time.find((x) => x.id === id && x.orgId === orgId)
            if (!t || (!isOffice() && t.operatorId !== myOperator()?.id)) throw notFound('time entry')
            if (at < t.start) throw invalid('clock stops before it started')
            t.end = at
            return t
          }).then((t) => done(out(t))),
        forJob: (jobId) =>
          run(() => {
            findJob(jobId)
            const me = myOperator()?.id
            return db.time.filter((t) => t.jobId === jobId && (isOffice() || t.operatorId === me)).map((t) => out(t))
          }),
      },

      photos: {
        add: (p) =>
          run(() => {
            actingAs(p.operatorId, findJob(p.jobId))
            const photo = { ...p, id: newId('pho'), orgId }
            db.photos.push(photo)
            return photo
          }).then((p) => done(out(p))),
        forJob: (jobId) => run(() => (findJob(jobId), db.photos.filter((p) => p.jobId === jobId).map((p) => out(p)))),
      },

      reports: {
        forJob: (jobId) => run(() => (findJob(jobId), db.reports.filter((r) => r.orgId === orgId && r.jobId === jobId).map((r) => out(r)))),
        save: (jobId, input) =>
          run(() => {
            const job = editableJob(jobId)
            const op = actingAs(input.operatorId, job)
            const segments = checkSegments(input.segments)
            if (!segments.length && input.ticked === undefined) throw invalid('the report needs something said')
            if (db.reports.some((r) => r.orgId === orgId && r.jobId === jobId && r.operatorId === op.id && r.status === 'signed')) throw invalid('the job report is already signed off')
            const items = db.priceList.filter((i) => i.orgId === orgId)
            const built = buildReport({ segments, trade: job.trade, priceList: items, van: db.stock.filter((x) => x.orgId === orgId && x.operatorId === op.id) })
            const was = db.reports.find((r) => r.orgId === orgId && r.jobId === jobId && r.operatorId === op.id && r.status === 'draft')
            const parts = input.parts ? checkParts(input.parts, segments, items) : built.parts
            const ticked = input.ticked === undefined ? was?.ticked : checkTicks(input.ticked)
            const now = new Date().toISOString()
            const report: Owned<JobReport> = { ...withTicks(built, parts, ticked), id: was?.id ?? newId('rep'), jobId, operatorId: op.id, segments, status: 'draft', createdAt: was?.createdAt ?? now, updatedAt: now, orgId }
            db.reports = [...db.reports.filter((r) => r !== was), report]
            return report
          }).then((r) => done(out(r))),
        sign: (id) =>
          run(() => {
            const report = db.reports.find((r) => r.id === id && r.orgId === orgId)
            if (!report) throw notFound('job report')
            const job = editableJob(report.jobId)
            const op = actingAs(report.operatorId, job)
            if (report.status === 'signed') throw invalid('the job report is already signed off')
            const why = cantSign(report)
            if (why) throw invalid(why)
            const lines = partLines(report.parts, db.priceList.filter((i) => i.orgId === orgId), op.id)
            for (const l of lines) {
              if (l.fromVan && l.itemId) moveStock(l.fromVan, l.itemId, -l.quantity)
              job.lines.push({ ...l, id: newId('li') })
            }
            // A draft invoice already made from the job takes the parts too.
            const draft = db.invoices.find((i) => i.orgId === orgId && i.jobId === job.id && i.status === 'draft')
            if (draft) draft.lines.push(...lines.map(({ fromVan: _v, ...l }) => ({ ...l, id: newId('li') })))
            Object.assign(report, { status: 'signed', signedAt: new Date().toISOString(), signedBy: op.name })
            return report
          }).then((r) => done(out(r))),
      },

      notes: {
        add: (n) =>
          run(() => {
            if (!n.body.trim()) throw invalid('note is empty')
            actingAs(n.operatorId, findJob(n.jobId))
            const note = { ...n, id: newId('not'), orgId }
            db.notes.push(note)
            return note
          }).then((n) => done(out(n))),
        forJob: (jobId) => run(() => (findJob(jobId), db.notes.filter((n) => n.jobId === jobId).map((n) => out(n)))),
      },

      quotes: {
        list: () => run(() => (requireOffice('see every quote'), db.quotes.filter((q) => q.orgId === orgId).map((q) => out(q)))),
        forJob: (jobId) => run(() => (findJob(jobId), db.quotes.filter((q) => q.jobId === jobId).map((q) => out(q)))),
        create: (jobId, opts = {}) =>
          run(() => {
            requireOffice('write quotes')
            const job = findJob(jobId)
            const options = opts.options ? quoteOptions(opts.options) : undefined
            const lines = options ? structuredClone(options[0].lines) : opts.lines ? priced(opts.lines) : structuredClone(job.lines)
            const q: Owned<Quote> = {
              id: newId('quo'),
              ref: `Q-${nextNumber(orgId, 'quote')}`,
              jobId,
              customerId: job.customerId,
              lines,
              ...(options ? { options } : {}),
              status: 'draft',
              validUntil: opts.validUntil ?? new Date(Date.now() + 30 * DAY).toISOString().slice(0, 10),
              orgId,
            }
            db.quotes.push(q)
            return q
          }).then((q) => done(out(q))),
        update: (id, patch) =>
          run(() => {
            requireOffice('change quotes')
            const q = findQuote(id)
            if (q.status !== 'draft') throw invalid(`quote is ${q.status}; only a draft can change`)
            if (patch.options === null) delete q.options
            else if (patch.options) {
              q.options = quoteOptions(patch.options)
              q.lines = structuredClone(q.options[0].lines)
            }
            if (patch.lines && !q.options) q.lines = priced(patch.lines)
            if (patch.validUntil) q.validUntil = patch.validUntil
            return q
          }).then((q) => done(out(q))),
        send: (id) =>
          run(() => {
            requireOffice('send quotes')
            const q = findQuote(id)
            if (q.status !== 'draft' && q.status !== 'sent') throw invalid(`quote is ${q.status}`)
            q.status = 'sent'
            q.sentAt = new Date().toISOString()
            const job = findJob(q.jobId)
            if (job.status === 'enquiry') job.status = 'quoted'
            return q
          }).then((q) => done(out(q))),
        respond: (id, answer, option) =>
          run(() => {
            requireOffice('record a customer’s answer')
            const q = findQuote(id)
            if (q.status !== 'sent') throw invalid(`quote is ${q.status}`)
            if (answer === 'accepted' && q.options) {
              const picked = q.options.find((o) => o.key === option)
              if (!picked) throw invalid(`say which option they chose: ${q.options.map((o) => o.key).join(', ')}`)
              q.chosen = picked.key
              q.lines = structuredClone(picked.lines)
            }
            q.status = answer
            const job = findJob(q.jobId)
            if (answer === 'accepted' && (job.status === 'enquiry' || job.status === 'quoted')) {
              job.status = 'booked'
              job.lines = structuredClone(q.lines)
            }
            if (answer === 'accepted') payments.askDeposit(q)
            return q
          }).then((q) => done(out(q))),
      },

      signatures: {
        add: (sig) =>
          run(() => {
            actingAs(sig.operatorId, findJob(sig.jobId))
            const s = { ...sig, id: newId('sig'), orgId }
            db.signatures.push(s)
            return s
          }).then((s) => done(out(s))),
        forJob: (jobId) => run(() => (findJob(jobId), db.signatures.filter((s) => s.jobId === jobId).map((s) => out(s)))),
      },

      // Engineers invoice and take payment on the doorstep, so Field can do
      // these on their own jobs. The job's status follows the invoice.
      invoices: {
        list: () => run(() => (requireOffice('see every invoice'), db.invoices.filter((i) => i.orgId === orgId).map((i) => out(i)))),
        forJob: (jobId) => run(() => (findJob(jobId), db.invoices.filter((i) => i.jobId === jobId).map((i) => out(i)))),
        create: (jobId, opts = {}) =>
          run(() => {
            const job = findJob(jobId)
            if (job.status === 'cancelled') throw invalid('job is cancelled')
            // Ardent drafts one when the job is finished; asking again hands that one over.
            const drafted = db.invoices.find((i) => i.jobId === jobId && i.orgId === orgId && i.status === 'draft')
            if (drafted) return drafted
            // One raised on a phone with no signal may already be here through its pay code.
            const viaCode = opts.offlineId && db.invoices.find((i) => i.jobId === jobId && i.orgId === orgId && i.offlineId === opts.offlineId)
            if (viaCode) return viaCode
            const inv: Owned<Invoice> = {
              id: newId('inv'),
              ref: `INV-${nextNumber(orgId, 'invoice')}`,
              jobId,
              customerId: job.customerId,
              lines: structuredClone(job.lines),
              vatRate: opts.vatRate ?? 2000,
              status: 'draft',
              paidAmount: 0,
              ...(opts.offlineId ? { offlineId: opts.offlineId } : {}),
              orgId,
            }
            db.invoices.push(inv)
            payments.applyDeposits(inv)
            return inv
          }).then((i) => done(out(i))),
        send: (id) =>
          run(() => {
            const inv = findInvoice(id)
            if (inv.status === 'void' || inv.status === 'paid') throw invalid(`invoice is ${inv.status}`)
            const now = Date.now()
            const total = invoiceTotals(inv).total
            inv.status = inv.paidAmount >= total ? 'paid' : inv.paidAmount > 0 ? 'part_paid' : 'sent'
            inv.issuedAt = new Date(now).toISOString()
            inv.dueAt = new Date(now + 14 * DAY).toISOString()
            findJob(inv.jobId).status = inv.status === 'paid' ? 'paid' : 'invoiced'
            // Every invoice carries a Pay now link once the firm takes payments.
            payments.invoiceLink(inv)
            return inv
          }).then((i) => done(out(i))),
        recordPayment: (id, amount, method) =>
          run(() => {
            const inv = findInvoice(id)
            if (!Number.isInteger(amount) || amount <= 0) throw invalid('payment is whole pence above zero')
            if (inv.status === 'void') throw invalid('invoice is void')
            const total = invoiceTotals(inv).total
            const taken = Math.min(total - inv.paidAmount, amount)
            if (taken > 0) (inv.payments ??= []).push({ amount: taken, method: method ?? 'bank_transfer', at: new Date().toISOString() })
            inv.paidAmount = Math.min(total, inv.paidAmount + amount)
            inv.status = inv.paidAmount >= total ? 'paid' : 'part_paid'
            inv.issuedAt ??= new Date().toISOString()
            findJob(inv.jobId).status = inv.status === 'paid' ? 'paid' : 'invoiced'
            return inv
          }).then((i) => done(out(i))),
      },

      // Taking payments through the firm's own Stripe account: see payments.ts.
      ...payments.client({ orgId, isOffice, isOwner, requireOffice, myOperatorId: () => myOperator()?.id, findInvoice, me: () => me(), run, done, out }),
    }

    const me = () => db.users.find((u) => u.id === userId) ?? { id: userId, name: 'Someone' }

    /**
     * What Ardent has ready for a yes, worked out from the records: draft
     * invoices and quotes to send, overdue invoices to chase. A waiting one
     * follows its record as it changes; one no longer needed goes stale; one
     * turned down stays down until its record changes. True when anything moved.
     */
    function syncApprovals() {
      const now = new Date()
      const iso = now.toISOString()
      const rules = rulesFor(orgId)
      const firm = rules.signOff ?? db.orgs.find((o) => o.id === orgId)?.name ?? 'us'
      const sends = levelOf(rules, 'draft_invoice') ?? 0
      const chases = levelOf(rules, 'invoice_chasing') ?? 0
      const quoting = levelOf(rules, 'quote_drafts') ?? 0
      const wanted: Omit<Approval, 'id' | 'status' | 'createdAt'>[] = []
      const customer = (id: string) => db.customers.find((c) => c.id === id && c.orgId === orgId)
      const hello = (id: string) => {
        const c = customer(id)
        const person = c && (c.kind === 'homeowner' || c.kind === 'landlord')
        if (rules.tone === 'formal') return person ? `Dear ${c.name}` : 'Dear Sir or Madam'
        if (!person) return 'Hello'
        return `${rules.tone === 'plain' ? 'Hello' : 'Hi'} ${c.name.split(' ')[0]}`
      }
      // Reminders already sent to a customer this week, across all their invoices.
      const lately = (customerId: string) =>
        db.invoices
          .filter((i) => i.orgId === orgId && i.customerId === customerId)
          .flatMap((i) => i.reminders ?? [])
          .filter((at) => now.getTime() - Date.parse(at) < 7 * DAY).length
      for (const inv of db.invoices.filter((i) => i.orgId === orgId)) {
        const job = db.jobs.find((j) => j.id === inv.jobId)
        const c = customer(inv.customerId)
        const total = invoiceTotals(inv).total
        if (sends && inv.status === 'draft' && inv.lines.length && job && job.status !== 'cancelled') {
          const site = db.sites.find((x) => x.id === job.siteId)
          wanted.push({
            kind: 'send_invoice',
            title: `Send ${inv.ref} to ${c?.name ?? 'the customer'}`,
            why: `${job.ref} ${job.title}${DONE_JOB.includes(job.status) ? ', finished' : ''}. ${inv.lines.length} ${inv.lines.length === 1 ? 'line' : 'lines'}, ${pounds(total)} with VAT.`,
            preview: `${hello(inv.customerId)}, thanks for having us${site ? ` at ${site.line1}` : ''}. Your invoice ${inv.ref} for ${pounds(total)} is attached, due within 14 days.${payments.active(orgId) ? ' It has a Pay now link: pay by bank or card.' : ''} ${firm}`,
            version: `${total}.${inv.lines.length}.${inv.customerId}`,
            jobId: job.id,
            invoiceId: inv.id,
          })
        }
        const last = inv.reminders?.at(-1)
        const late = inv.dueAt ? Math.floor((now.getTime() - Date.parse(inv.dueAt)) / DAY) : -1
        if (
          chases &&
          OWING.includes(inv.status) &&
          inv.dueAt &&
          inv.dueAt < iso &&
          late >= rules.chase.first &&
          (!last || now.getTime() - Date.parse(last) > rules.chase.gap * DAY) &&
          lately(inv.customerId) < rules.limits.messagesPerCustomerWeek
        ) {
          const owed = total - inv.paidAmount
          const step = late >= rules.chase.statement ? 'statement' : late >= rules.chase.firmer ? 'firmer' : 'friendly'
          wanted.push({
            kind: 'chase_invoice',
            title: `${step === 'statement' ? 'Send a statement to' : 'Remind'} ${c?.name ?? 'the customer'}${step === 'statement' ? ' for' : ' about'} ${inv.ref}`,
            why: `${pounds(owed)} owed, ${late} ${late === 1 ? 'day' : 'days'} past due${inv.reminders?.length ? `, ${inv.reminders.length} reminder${inv.reminders.length === 1 ? '' : 's'} so far` : ', no reminder yet'}.`,
            preview:
              step === 'statement'
                ? `${hello(inv.customerId)}, this is a statement for invoice ${inv.ref}: ${pounds(owed)} is still owed and it is ${late} days overdue. Please pay it now, or ring us so we can sort it out.${payments.payLine(inv)} ${firm}`
                : step === 'firmer'
                  ? `${hello(inv.customerId)}, invoice ${inv.ref} for ${pounds(owed)} is now ${late} days overdue. Please pay it this week, or reply if something's wrong with it.${payments.payLine(inv)} ${firm}`
                  : `${hello(inv.customerId)}, a friendly reminder that invoice ${inv.ref} for ${pounds(owed)} was due on ${shortDate(inv.dueAt)}. If you've already paid, thank you and please ignore this.${payments.payLine(inv)} ${firm}`,
            version: `${owed}.${inv.reminders?.length ?? 0}.${step}`,
            jobId: inv.jobId,
            invoiceId: inv.id,
          })
        }
      }
      for (const q of db.quotes.filter((x) => quoting && x.orgId === orgId && x.status === 'draft' && x.lines.length)) {
        const job = db.jobs.find((j) => j.id === q.jobId)
        const net = q.lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0)
        wanted.push({
          kind: 'send_quote',
          title: `Send ${q.ref} to ${customer(q.customerId)?.name ?? 'the customer'}`,
          why: `${job ? `${job.ref} ${job.title}. ` : ''}${q.options ? `${q.options.length} options, from ${pounds(Math.min(...q.options.map((o) => o.lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0))))}` : pounds(net)} before VAT, valid until ${shortDate(`${q.validUntil}T12:00:00Z`)}.`,
          preview: `${hello(q.customerId)}, here's our quote ${q.ref}${q.options ? ` with ${q.options.length} options to choose from` : ''}. It's valid until ${shortDate(`${q.validUntil}T12:00:00Z`)}. Reply or ring us with any questions. ${firm}`,
          version: `${net}.${q.options?.length ?? 0}.${q.lines.length}`,
          jobId: q.jobId,
          quoteId: q.id,
        })
      }

      // Money going back out always waits for a person's yes.
      wanted.push(...payments.refundApprovals(orgId))

      let changed = false
      const target = (a: Pick<Approval, 'kind' | 'invoiceId' | 'quoteId' | 'refundId'>) => `${a.kind}:${a.refundId ?? a.invoiceId ?? a.quoteId}`
      const keys = new Set(wanted.map(target))
      for (const a of db.approvals.filter((x) => x.orgId === orgId && x.status === 'waiting' && !keys.has(target(x)))) {
        a.status = 'stale'
        const off = a.kind !== 'refund' && !(a.kind === 'send_invoice' ? sends : a.kind === 'chase_invoice' ? chases : quoting)
        a.note = off ? "switched off in Ardent's rules" : 'done another way, or no longer needed'
        a.decidedAt = iso
        changed = true
      }
      for (const w of wanted) {
        const mine = db.approvals.filter((x) => x.orgId === orgId && target(x) === target(w))
        const open = mine.find((x) => x.status === 'waiting')
        if (open) {
          if (open.version !== w.version || open.preview !== w.preview || open.why !== w.why) {
            Object.assign(open, w)
            changed = true
          }
          continue
        }
        if (mine.some((x) => x.version === w.version && (x.status === 'rejected' || x.status === 'approved'))) continue
        db.approvals.push({ ...w, id: newId('apr'), status: 'waiting', createdAt: iso, orgId })
        changed = true
      }
      return changed
    }

    /**
     * A finished job with nothing billed gets a draft invoice from Ardent: the
     * parts and work on the job, and the time on site when no labour is
     * priced yet, at the firm's hourly rate. It waits for a yes before it goes.
     */
    function draftInvoice(job: Owned<Job>) {
      if (!levelOf(rulesFor(orgId), 'draft_invoice')) return
      if (db.invoices.some((i) => i.jobId === job.id && i.orgId === orgId && i.status !== 'void')) return
      const lines = structuredClone(job.lines)
      let hours = 0
      if (!lines.some((l) => l.kind === 'labour')) {
        const ms = db.time
          .filter((t) => t.orgId === orgId && t.jobId === job.id && t.kind === 'labour' && t.end)
          .reduce((sum, t) => sum + Date.parse(t.end!) - Date.parse(t.start), 0)
        hours = Math.ceil(ms / (15 * 60_000)) / 4
        const rate = db.priceList.find((i) => i.orgId === orgId && i.kind === 'labour' && i.unit === 'hour' && !i.archived)
        if (hours > 0 && rate) lines.push({ id: newId('li'), kind: 'labour', description: `Time on site, ${hours} ${hours === 1 ? 'hour' : 'hours'}`, quantity: hours, unitPrice: rate.price, itemId: rate.id })
        else hours = 0
      }
      if (!lines.length) return
      const inv: Owned<Invoice> = { id: newId('inv'), ref: `INV-${nextNumber(orgId, 'invoice')}`, jobId: job.id, customerId: job.customerId, lines, vatRate: 2000, status: 'draft', paidAmount: 0, orgId }
      db.invoices.push(inv)
      payments.applyDeposits(inv)
      const parts = lines.filter((l) => l.kind === 'material').length
      const from = [parts ? `${parts} ${parts === 1 ? 'part' : 'parts'}` : '', hours ? `${hours} ${hours === 1 ? 'hour' : 'hours'} on site` : ''].filter(Boolean).join(' and ')
      db.actions.push({ id: newId('act'), at: new Date().toISOString(), by: { kind: 'ardent' }, action: 'invoices.create', summary: `Drafted ${inv.ref} for ${job.ref}${from ? ` from ${from}` : ''}, waiting for a yes`, level: 'draft', jobId: job.id, orgId })
    }

    /** Put an offer in front of one engineer, with their time to answer. */
    function sendOffer(req: JobRequest, o: JobOffer, now: number) {
      o.status = 'offered'
      o.offeredAt = new Date(now).toISOString()
      o.expiresAt = new Date(now + req.wait * 1000).toISOString()
    }

    /**
     * Move a request on: offers past their time expire, the next engineer in
     * line gets it, and when no one is left it's unfilled. Worked out when
     * anyone looks, so no timer is needed. True when anything changed.
     */
    function advance(req: Owned<JobRequest>) {
      if (req.status !== 'open') return false
      const now = Date.now()
      let changed = false
      const job = db.jobs.find((j) => j.id === req.jobId && j.orgId === req.orgId)
      if (!job || CLOSED.includes(job.status)) {
        req.status = 'withdrawn'
        for (const o of req.offers) if (o.status === 'offered' || o.status === 'waiting') o.status = 'closed'
        return true
      }
      for (const o of req.offers) {
        if (o.status === 'offered' && Date.parse(o.expiresAt!) <= now) {
          o.status = 'expired'
          changed = true
        }
      }
      if (req.mode === 'one' && !req.offers.some((o) => o.status === 'offered')) {
        const next = req.offers.find((o) => o.status === 'waiting')
        if (next) {
          sendOffer(req, next, now)
          changed = true
        }
      }
      if (!req.offers.some((o) => o.status === 'offered' || o.status === 'waiting')) {
        req.status = 'unfilled'
        changed = true
      }
      return changed
    }

    /** What an engineer sees of a request: the brief and their own offer, nothing about anyone else. */
    function fieldView(req: Owned<JobRequest>, operatorId: string): JobRequest {
      const r = out(req) as JobRequest
      r.offers = r.offers.filter((o) => o.operatorId === operatorId)
      r.skipped = []
      if (r.filledBy !== operatorId) delete r.filledBy
      return r
    }

    /** Papers for a trade that are in date, or why not. */
    function papersFor(op: OperatorRow, trade: Trade, today: string) {
      const need = PAPERS[trade]
      if (need) {
        const held = op.registrations.filter((r) => need.includes(r.body))
        if (!held.length) return `No ${need[0]} card`
        if (!held.some((r) => r.expires >= today)) return `${held[0].body} lapsed`
      }
      if (op.role === 'subcontractor' || op.role === 'freelance') {
        const cover = op.registrations.filter((r) => r.body === 'Public liability')
        if (!cover.length) return 'No insurance on file'
        if (!cover.some((r) => r.expires >= today)) return 'Insurance lapsed'
      }
      return undefined
    }

    /** Everyone who could be sent to a job, nearest first, and why the rest can't. */
    function whoCanGo(job: Owned<Job>, site: { lat: number; lng: number }) {
      const now = Date.now()
      const today = new Date(now).toISOString().slice(0, 10)
      const going: { op: OperatorRow; start: { lat: number; lng: number }; miles: number; minutes?: number; by?: DriveTime['by']; known: boolean }[] = []
      const skipped: JobRequest['skipped'] = []
      for (const op of db.operators.filter((o) => o.orgId === orgId)) {
        const skip = (why: string) => skipped.push({ operatorId: op.id, why })
        if (!op.userId || !db.memberships.some((m) => m.orgId === orgId && m.userId === op.userId)) { skip('No Ardent Field sign-in'); continue }
        if (!op.trades.includes(job.trade)) { skip(`Not ${TRADE_NAME[job.trade]}`); continue }
        const papers = papersFor(op, job.trade, today)
        if (papers) { skip(papers); continue }
        const onStandby = !!op.standby && Date.parse(op.standby.until) > now
        if (op.role === 'freelance' && !onStandby) { skip('Not on standby'); continue }
        if (op.state === 'off_shift') { skip('Off shift'); continue }
        if (BUSY.includes(op.state) && op.currentJobId !== job.id) {
          skip(`On ${db.jobs.find((j) => j.id === op.currentJobId)?.ref ?? 'a job'}`)
          continue
        }
        const at = whereIs(op, now)?.start ?? (onStandby ? op.standby!.base : undefined)
        const miles = at ? Math.round(milesApart(at, site) * 10) / 10 : Infinity
        if (op.role === 'freelance') {
          if (!at) { skip("Can't see where they are"); continue }
          if (miles > op.standby!.radius) { skip(`Outside their ${op.standby!.radius} miles`); continue }
        }
        going.push({ op, start: at ?? { lat: site.lat, lng: site.lng }, miles, known: !!at })
      }
      going.sort((a, b) => a.miles - b.miles)
      return { going, skipped }
    }

    /** A van's row for an item, made at zero the first time it's needed. */
    function stockRow(operatorId: string, itemId: string) {
      let row = db.stock.find((x) => x.orgId === orgId && x.operatorId === operatorId && x.itemId === itemId)
      if (!row) {
        row = { operatorId, itemId, quantity: 0, min: 0, orgId }
        db.stock.push(row)
      }
      return row
    }
    /** Parts out of (or back onto) a van. A count that's already off never goes below zero. */
    function moveStock(operatorId: string, itemId: string, by: number) {
      const row = stockRow(operatorId, itemId)
      row.quantity = Math.max(0, row.quantity + by)
    }

    function checkItem<T extends Omit<PriceItem, 'id'>>(i: T): T {
      if (!i.name?.trim()) throw invalid('the item needs a name')
      if (!PRICE_KINDS.includes(i.kind)) throw invalid(`unknown kind ${i.kind}`)
      if (!PRICE_UNITS.includes(i.unit)) throw invalid(`unknown unit ${i.unit}`)
      if (!Number.isInteger(i.price) || i.price < 0) throw invalid('price is whole pence of zero or more')
      if (i.cost !== undefined && (!Number.isInteger(i.cost) || i.cost < 0)) throw invalid('cost is whole pence of zero or more')
      return { ...i, name: i.name.trim(), code: i.code?.trim() || undefined, stocked: !!i.stocked }
    }

    /** What the engineer said, as the phone sends it: some words, each with a time. */
    function checkSegments(input: unknown): ReportSegment[] {
      // Empty only while they've just ticked what happened; signing needs words.
      if (!Array.isArray(input)) throw invalid('the report needs something said')
      if (input.length > 200) throw invalid('the report is too long')
      return input.map((x) => {
        const seg = x as Partial<ReportSegment>
        const text = typeof seg?.text === 'string' ? seg.text.trim() : ''
        if (!text) throw invalid('every part of the report needs words')
        if (text.length > 4000) throw invalid('one part of the report is too long')
        if (typeof seg.at !== 'string' || Number.isNaN(Date.parse(seg.at))) throw invalid('every part of the report needs a time')
        const topics = ['work', 'parts', 'tests', 'left', 'next']
        if (seg.topic !== undefined && !topics.includes(seg.topic)) throw invalid('unknown report topic')
        if (seg.moved !== undefined && (!Array.isArray(seg.moved) || seg.moved.length > 50 || seg.moved.some((m) => !topics.includes(m?.topic) || !(Number.isInteger(m.start) && Number.isInteger(m.end) && m.start >= 0 && m.start < m.end && m.end <= text.length)))) throw invalid('a moved sentence must point at its words')
        if (seg.followUp !== undefined && !(typeof seg.followUp === 'string' && /^[a-z0-9-]{1,60}$/.test(seg.followUp))) throw invalid('unknown follow-up')
        return {
          text,
          at: seg.at,
          ...(seg.topic ? { topic: seg.topic } : {}),
          ...(seg.moved?.length ? { moved: seg.moved.map(({ start, end, topic }) => ({ start, end, topic })) } : {}),
          ...(seg.followUp ? { followUp: seg.followUp } : {}),
        }
      })
    }

    function checkTicks(input: unknown): ReportTick[] {
      if (!Array.isArray(input) || input.some((t) => !TICKS.some((x) => x.tick === t))) throw invalid('unknown tick on the report')
      return TICKS.map((x) => x.tick).filter((t) => input.includes(t))
    }

    /** The engineer's own pick for each part: a real item, a count, and the words it came from (or picked from the van list). */
    function checkParts(input: ReportPart[], segments: ReportSegment[], items: PriceItem[]): ReportPart[] {
      if (!Array.isArray(input) || input.length > 100) throw invalid('too many parts')
      return input.map((p) => {
        if (p.itemId && !items.some((i) => i.id === p.itemId)) throw notFound('price list item')
        if (!(p.quantity > 0) || p.quantity > 10_000) throw invalid('quantity must be more than zero')
        const seg = segments[p.from?.segment]
        if (!p.picked && (!seg || !(p.from.start >= 0 && p.from.end <= seg.text.length && p.from.start < p.from.end))) throw invalid('every part must point at the words it came from')
        if (p.picked && !p.itemId && !String(p.description ?? '').trim()) throw invalid('a typed part needs a name')
        const item = items.find((i) => i.id === p.itemId)
        return {
          ...(p.itemId ? { itemId: p.itemId } : {}),
          description: item?.name ?? String(p.description ?? '').slice(0, 200),
          quantity: p.quantity,
          unit: item?.unit ?? p.unit,
          quantitySaid: !!p.quantitySaid,
          fromVan: !!p.fromVan,
          sourceSaid: !!p.sourceSaid,
          heard: String(p.heard ?? '').slice(0, 500),
          from: p.picked ? { segment: -1, start: 0, end: 0 } : { segment: p.from.segment, start: p.from.start, end: p.from.end },
          ...(p.picked ? { picked: true } : {}),
          ...(!p.itemId && p.choices?.length ? { choices: p.choices.filter((c) => items.some((i) => i.id === c)) } : {}),
        }
      })
    }

    /** Lines in, with ids, checked the way addLine checks them. */
    function priced(lines: Omit<LineItem, 'id'>[]): LineItem[] {
      return lines.map((l) => {
        if (!String(l.description ?? '').trim()) throw invalid('every line needs a description')
        if (!(l.quantity > 0)) throw invalid('quantity must be more than zero')
        if (!Number.isInteger(l.unitPrice)) throw invalid('unit price is whole pence')
        const { fromVan: _v, ...rest } = structuredClone(l)
        return { ...rest, id: newId('li') }
      })
    }

    function quoteOptions(input: { key: OptionKey; label: string; lines: Omit<LineItem, 'id'>[] }[]) {
      if (input.length < 2 || input.length > 3) throw invalid('offer two or three options')
      return input.map((o, i) => {
        if (o.key !== OPTION_KEYS[i]) throw invalid('options go A, B, C in order')
        if (!o.label?.trim()) throw invalid(`option ${o.key} needs a name`)
        if (!o.lines?.length) throw invalid(`option ${o.key} has no lines`)
        return { key: o.key, label: o.label.trim(), lines: priced(o.lines) }
      })
    }

    /** A record the caller may still fill in: a draft, on a job they can add to. */
    function draftRecord(id: string) {
      const rec = db.gasRecords.find((r) => r.id === id && r.orgId === orgId)
      if (!rec) throw notFound('gas safety record')
      editableJob(rec.jobId)
      if (rec.status !== 'draft') throw invalid(`${rec.ref} is already issued`)
      return rec
    }

    function findQuote(id: string) {
      const q = db.quotes.find((x) => x.id === id && x.orgId === orgId)
      if (!q) throw notFound('quote')
      findJob(q.jobId)
      return q
    }

    /** What a customer owes: everything sent and not yet paid. */
    function withBalance(c: Owned<Customer>): Customer {
      const balance = db.invoices
        .filter((i) => i.orgId === orgId && i.customerId === c.id && OWING.includes(i.status))
        .reduce((sum, i) => sum + invoiceTotals(i).total - i.paidAmount, 0)
      return { ...out(c), balance }
    }

    function findInvoice(id: string) {
      const inv = db.invoices.find((i) => i.id === id && i.orgId === orgId)
      if (!inv) throw notFound('invoice')
      findJob(inv.jobId)
      return inv
    }

    /** Firm admin, beyond what the shared client covers. */
    const admin = {
      /** Everyone in the firm with their role and name. */
      members: () =>
        run(() => {
          membership()
          return db.memberships
            .filter((m) => m.orgId === orgId)
            .map((m) => {
              const u = db.users.find((x) => x.id === m.userId)
              return { ...m, name: u?.name ?? '', email: u?.email ?? '', operatorId: db.operators.find((o) => o.orgId === orgId && o.userId === m.userId)?.id }
            })
        }),
      /** Owners add people, change roles and remove members, but never themselves. */
      setRole: (memberUserId: string, role: Role | null) =>
        run(() => {
          if (!isOwner()) throw forbidden('only the owner manages members')
          if (memberUserId === userId) throw forbidden("owners can't change their own role")
          if (!db.users.some((u) => u.id === memberUserId)) throw notFound('user')
          const i = db.memberships.findIndex((m) => m.orgId === orgId && m.userId === memberUserId)
          if (role === null) {
            if (i >= 0) db.memberships.splice(i, 1)
          } else if (i >= 0) db.memberships[i].role = role
          else db.memberships.push({ orgId, userId: memberUserId, role })
          store.commit()
        }),
      /** Link a crew record to someone's sign-in, so Field knows who they are. */
      linkOperator: (operatorId: string, operatorUserId: string | null) =>
        run(() => {
          requireOffice('link crew to sign-ins')
          const op = db.operators.find((o) => o.id === operatorId && o.orgId === orgId)
          if (!op) throw notFound('operator')
          op.userId = operatorUserId ?? undefined
          store.commit()
        }),
      role: () => run(() => membership().role),
      /**
       * Give someone a sign-in for this firm. Owners only. A new person gets
       * the temporary password given here; someone who already has an Ardent
       * sign-in (another firm) keeps their own.
       */
      invite: (input: { email: string; name: string; role: Role; password: string; operatorId?: string }) =>
        run(() => {
          if (!isOwner()) throw forbidden('only the owner adds people')
          if (!['owner', 'office', 'field'].includes(input.role)) throw invalid(`unknown role ${input.role}`)
          const email = String(input.email ?? '').trim().toLowerCase()
          const existing = db.users.find((u) => u.email === email)
          const user = existing ? publicUser(existing) : addUser({ email, name: input.name, password: input.password })
          if (db.memberships.some((m) => m.orgId === orgId && m.userId === user.id)) throw invalid('already in the firm')
          db.memberships.push({ orgId, userId: user.id, role: input.role })
          if (input.operatorId) {
            const op = db.operators.find((o) => o.id === input.operatorId && o.orgId === orgId)
            if (!op) throw notFound('operator')
            op.userId = user.id
          }
          store.commit()
          return user
        }),
      /** Add someone to the crew list (they can be given a sign-in later). */
      addOperator: (input: Omit<Operator, 'id' | 'state' | 'currentJobId' | 'etaMinutes'>) =>
        run(() => {
          requireOffice('add crew')
          if (!input.name?.trim()) throw invalid('a name is needed')
          const op = { ...structuredClone(input), id: newId('opr'), state: 'off_shift' as const, orgId }
          db.operators.push(op)
          store.commit()
          return out(op) as Operator
        }),
      /** Record that a photo's image has landed; returns where the file belongs. */
      photoUploaded: (photoId: string, ext: string) =>
        run(() => {
          const p = db.photos.find((x) => x.id === photoId && x.orgId === orgId)
          if (!p) throw notFound('photo')
          const job = findJob(p.jobId)
          if (!isOffice() && (p.operatorId !== myOperator()?.id || !assigned(job))) throw forbidden("can't change someone else's photo")
          p.uri = `ardent:photo/${p.id}`
          store.commit()
          return { file: `${orgId}/${p.id}.${ext}`, uri: p.uri }
        }),
      /** A link to a photo's image that works for an hour, for showing it on screen. */
      photoLink: (photoId: string) =>
        run(() => {
          const p = db.photos.find((x) => x.id === photoId && x.orgId === orgId)
          if (!p) throw notFound('photo')
          findJob(p.jobId)
          const exp = Date.now() + 60 * 60 * 1000
          return `/files/photos/${p.id}?exp=${exp}&sig=${sign(`${p.id}:${exp}`)}`
        }),
    }

    const look: Look = {
      job: (id) => db.jobs.find((j) => j.id === id && j.orgId === orgId),
      customer: (id) => db.customers.find((c) => c.id === id && c.orgId === orgId),
      operator: (id) => db.operators.find((o) => o.id === id && o.orgId === orgId),
      invoice: (id) => db.invoices.find((i) => i.id === id && i.orgId === orgId),
      quote: (id) => db.quotes.find((q) => q.id === id && q.orgId === orgId),
    }
    /** Every change through the client goes in the firm's log once it has worked. */
    function record(method: string, args: unknown[], result: unknown) {
      const person = { kind: 'person' as const, name: me().name, userId }
      let entry: Omit<ActionEntry, 'id' | 'at'>
      if (method === 'approvals.approve') {
        const a = result as Approval
        entry = { by: person, action: method, summary: `Said yes to Ardent's draft: ${a.title}`, level: 'approve', jobId: a.jobId, approvalId: a.id }
      } else if (method === 'approvals.reject') {
        const a = result as Approval
        entry = { by: person, action: method, summary: `Said no to Ardent's draft: ${a.title}`, jobId: a.jobId, approvalId: a.id }
      } else {
        const { summary, jobId } = describe(method, args, result, look)
        if (!summary) return
        entry = { by: person, action: method, summary, ...(jobId ? { jobId } : {}) }
      }
      db.actions.push({ ...entry, id: newId('act'), at: new Date().toISOString(), orgId })
      if (db.actions.length > LOG_KEEP) db.actions.splice(0, db.actions.length - LOG_KEEP)
      store.commit()
    }
    const logged = Object.fromEntries(
      Object.entries(client).map(([area, group]) => [
        area,
        Object.fromEntries(
          Object.entries(group as Record<string, (...a: unknown[]) => Promise<unknown>>).map(([name, fn]) => {
            const method = `${area}.${name}`
            if (/^(list|get|forJob|me)$/.test(name)) return [name, fn]
            return [name, async (...args: unknown[]) => {
              const result = await fn(...args)
              record(method, args, result)
              return result
            }]
          }),
        ),
      ]),
    ) as unknown as ArdentClient

    return { client: logged, admin }
  }

  /** Ardent HQ, for Ardent's own team: every firm, read across. */
  const hq = (userId: string) => hqFor({ db, store, usageOf, rulesFor, followUpsFor, newId, forbidden, notFound, invalid, paymentsAcross: payments.acrossFirms }, userId)
  /** Ardent staff, for the sign-in to Ardent HQ. */
  const isStaff = (userId: string) => db.staff.some((s) => s.userId === userId)

  /** Stripe told the engine something (the webhook), or a customer opened a pay link. */
  const paymentEvent = payments.event
  const stripeWebhook = payments.webhook
  const openPayLink = payments.open

  return { addUser, createOrganisation, organisationsFor, signUp, login, logout, userForToken, recall, remember, photoForLink, as, hq, isStaff, allowance, meter, paymentEvent, stripeWebhook, openPayLink, data: db }
}

export type Engine = ReturnType<typeof createEngine>
// Re-exported so callers needn't reach into the model for line shapes.
export type { LineItem }
